// SECURE: Request validation to block property traversal
package com.example.security;

import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import javax.servlet.FilterChain;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

@Component
public class Spring4ShellProtectionFilter extends OncePerRequestFilter {

    private static final String[] BLOCKED_PATTERNS = {
        "class.",
        "Class.",
        "*.classLoader",
        "*.getClass",
        "*.forName",
        "*.newInstance"
    };

    @Override
    protected void doFilterInternal(
            HttpServletRequest request,
            HttpServletResponse response,
            FilterChain filterChain) throws ServletException, IOException {

        // ✅ SECURE: Check all query parameters and form data
        String queryString = request.getQueryString();
        String[] parts = request.getParameterNames().toString().split(",");

        for (String param : parts) {
            for (String blocked : BLOCKED_PATTERNS) {
                if (param.toLowerCase().contains(blocked.toLowerCase())) {
                    // Log suspicious activity
                    logger.warn("SECURITY: Spring4Shell exploitation attempt detected. " +
                        "Parameter: " + param + ", IP: " + request.getRemoteAddr());

                    // Return 400 Bad Request
                    response.setStatus(400);
                    response.getWriter().write("{\"error\": \"Invalid parameter\"}");
                    return;
                }
            }
        }

        filterChain.doFilter(request, response);
    }
}

// SECURE: Spring Security configuration to restrict POJO binding
@Configuration
public class WebMvcConfig implements WebMvcConfigurer {

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new HandlerInterceptor() {
            @Override
            public boolean preHandle(
                    HttpServletRequest request,
                    HttpServletResponse response,
                    Object handler) throws Exception {

                // ✅ SECURE: Only allow JSON requests (not form-encoded)
                String contentType = request.getContentType();

                // Reject form-encoded POJO binding
                if (contentType != null && 
                    contentType.contains("application/x-www-form-urlencoded")) {
                    // Allow only application/json
                    response.setStatus(415);
                    response.getWriter().write("{\"error\": \"Unsupported Media Type\"}" );
                    return false;
                }

                return true;
            }
        });
    }
}

// SECURE: WAF Rules (if using AWS WAF, Cloudflare, etc.)
/*
AWS WAF Rules:
- Block strings containing: "class.", "Class.", "classLoader"
- Pattern: ^.*\bclass\..*$
- Pattern: ^.*\.getClass.*$

Cloudflare WAF Rules:
- Block User-Agent + URI containing property traversal patterns
- Block POST data with parameter names containing "class"

CoreRuleSet (OWASP ModSecurity):
- Rule 942450: Detects "class." and "Class." patterns in request
- Rule 942451: Detects "classLoader" in request parameters
*/
```

### Tier 3: Production Hardening (30 minutes)

**Add Runtime Monitoring & Incident Response Automation**

```java
// SECURE: Runtime property binding detection and alerting
package com.example.security;

import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.ServletRequestBindingException;

@Component
@ControllerAdvice
public class Spring4ShellDetectionHandler {

    private static final Logger log = LoggerFactory.getLogger(Spring4ShellDetectionHandler.class);
    private final Counter exploitAttempts;
    private final Counter successfulBlocks;

    public Spring4ShellDetectionHandler(MeterRegistry registry) {
        this.exploitAttempts = Counter.builder("spring4shell.attempts")
            .description("Spring4Shell exploitation attempts detected")
            .tag("severity", "critical")
            .register(registry);

        this.successfulBlocks = Counter.builder("spring4shell.blocks")
            .description("Spring4Shell attacks successfully blocked")
            .tag("action", "blocked")
            .register(registry);
    }

    @ExceptionHandler(ServletRequestBindingException.class)
    public void handleBindingException(ServletRequestBindingException e, 
                                      HttpServletRequest request) {
        // ✅ SECURE: Detect binding failures that indicate Spring4Shell attempts
        String message = e.getMessage();

        if (message != null && message.toLowerCase().contains("class")) {
            exploitAttempts.increment();
            successfulBlocks.increment();

            log.error("CRITICAL SECURITY ALERT: Spring4Shell exploitation attempt detected!");
            log.error("  IP Address: {}", request.getRemoteAddr());
            log.error("  URI: {}", request.getRequestURI());
            log.error("  Query String: {}", request.getQueryString());
            log.error("  User-Agent: {}", request.getHeader("User-Agent"));
            log.error("  Error Message: {}", message);

            // ✅ SECURE: Send alert to incident response team
            sendSecurityAlert(
                "Spring4Shell (CVE-2022-22965) Exploitation Attempt",
                request.getRemoteAddr(),
                request.getRequestURI()
            );
        }
    }

    private void sendSecurityAlert(String title, String attacker_ip, String target_uri) {
        // Send to SIEM, email, PagerDuty, Slack, etc.
        // Implementation depends on your alerting infrastructure
    }
}

